# CySA+ acronyms (176). The source is the class sheet ("CySA+ Acronyms with
# definitions", doc 3.001), all 175 entries, plus MTTR. Where the sheet is wrong, the
# correct expansion leads and the 'fix' note records what the sheet says.
# Notes are my own one-line analyst notes.
# Tuple: (acronym, expansion, note, objective[, fix]). 'o' = most relevant objective.
# CLASS_ONLY: kept for reference (sheet entries outside CompTIA's printed list); not shown.
ACR = [
('ACL','Access Control List','Ordered allow/deny rules on a router, firewall or file; first match wins, implicit deny at the end.','1.1'),
('API','Application Programming Interface','How tools talk to each other; SOAR and SIEM integrations run on vendor APIs, usually REST returning JSON.','1.5'),
('APT','Advanced Persistent Threat','Skilled, well-funded attacker who stays hidden for months; often state-backed.','1.4'),
('ARP','Address Resolution Protocol','Maps IP to MAC on a LAN; ARP spoofing enables on-path attacks. <code>arp -a</code> shows the cache.','1.2'),
('ASVS','Application Security Verification Standard','OWASP&rsquo;s list of security requirements a web app should meet, in three levels. You verify an app against ASVS; the Testing Guide tells you how to test.','2.4'),
('ATT&CK','Adversarial Tactics, Techniques, and Common Knowledge','MITRE&rsquo;s catalog of attacker tactics and techniques, each with an ID such as T1059. Map detections and incidents to it.','3.1'),
('AV','Antivirus','Signature-based malware detection; misses fileless and living-off-the-land attacks that EDR catches.','1.3'),
('BC','Business Continuity','Keeping critical business functions running during a disruption.','3.3'),
('BCP','Business Continuity Planning','The documented plan for BC; built on the BIA.','3.3'),
('BEAST','Browser Exploit Against SSL/TLS','2011 attack on CBC ciphers in SSL 3.0 and TLS 1.0 that recovers session cookies. One reason to disable old protocols.','2.4'),
('BGP','Border Gateway Protocol','Routes traffic between internet autonomous systems; BGP hijacks reroute traffic for whole prefixes.','1.1'),
('BIA','Business Impact Analysis','Identifies critical processes and sets RTO, RPO and MTD; drives recovery priorities.','3.3'),
('BIOS','Basic Input/Output System','Legacy firmware that starts the hardware and hands off to the boot loader. UEFI replaced it and adds Secure Boot.','1.1','Class sheet says &ldquo;Basic Input / Output&rdquo; and drops &ldquo;System&rdquo;.'),
('BREACH','Browser Reconnaissance & Exfiltration via Adaptive Compression of Hypertext','Uses HTTP compression to guess secrets in HTTPS responses one byte at a time. Mitigate by not compressing responses that carry secrets.','2.4'),
('C2','Command and Control','Attacker&rsquo;s channel to compromised hosts; spotted by beaconing, odd DNS, unusual outbound.','1.3'),
('CA','Certificate Authority','Signs certificates in a PKI; compromise of a CA undermines every certificate it issued.','1.1'),
('CASB','Cloud Access Security Broker','Visibility and policy between users and cloud apps; finds shadow IT, applies DLP to SaaS.','1.1'),
('CBC','Cipher Block Chaining','Block-cipher mode that mixes each block with the previous ciphertext. Needs an unpredictable IV; target of BEAST and padding-oracle attacks.','2.4','Class sheet says &ldquo;Cipher Block Chain&rdquo;; the mode is Chaining.'),
('CDN','Content Delivery Network','Distributed caching servers; also absorbs DDoS and can hide origin IPs.','1.1'),
('CERT','Computer Emergency Response Team','Coordinates response and publishes advisories, nationally or per organization; an open intel source.','1.4'),
('CHD','Cardholder Data','Card number plus name, expiry, service code; governed by PCI DSS.','1.1'),
('CI/CD','Continuous Integration and Continuous Delivery','Automated build-test-deploy pipeline; insert SAST, dependency and secrets scanning here.','2.5'),
('CIS','Center for Internet Security','Publishes CIS Benchmarks (hardening guides) and the CIS Controls.','2.1'),
('CMS','Content Management System','WordPress, Joomla, Drupal. Outdated plugins and themes are a leading way websites get compromised, so scan and patch them.','2.1'),
('COBIT','Control Objectives for Information and Related Technologies','ISACA&rsquo;s IT governance framework.','2.5'),
('CPU','Central Processing Unit','Sustained high CPU on a host that should be idle can mean cryptomining or password cracking.','1.2'),
('CSF','Cybersecurity Framework','Usually the NIST CSF: Govern (added in 2.0), Identify, Protect, Detect, Respond, Recover.','2.1'),
('CSIRT','Cybersecurity Incident Response Team','The team that handles incidents; also a source of shared threat intel.','3.3'),
('CSRF','Cross-site Request Forgery','Tricks a logged-in browser into sending an unwanted request; fix with anti-CSRF tokens and SameSite cookies.','2.4'),
('CVE','Common Vulnerabilities and Exposures','Unique ID for a public vulnerability (CVE-YYYY-NNNNN), run by MITRE.','2.3','Class sheet says &ldquo;Common Vulnerability Enumeration&rdquo;, which is wrong; CWE is the Common Weakness Enumeration.'),
('CVSS','Common Vulnerability Scoring System','0&ndash;10 severity from AV, AC, PR, UI, S and C/I/A impact.','2.3'),
('DAST','Dynamic Application Security Testing','Tests the running app from outside, the way an attacker would (ZAP, Burp). Finds runtime and configuration flaws but not the line of code.','2.1'),
('DDoS','Distributed Denial of Service','Many sources flooding a target; mitigate upstream (scrubbing, CDN).','1.2'),
('DEP','Data Execution Prevention','Marks memory such as the stack as non-executable so injected code can&rsquo;t run. Paired with ASLR against overflow exploits.','2.4'),
('DHCP','Dynamic Host Configuration Protocol','Hands out IP settings on UDP 67/68. DHCP logs tie an IP to a MAC and hostname at a point in time; a rogue DHCP server enables on-path attacks.','1.1'),
('DKIM','DomainKeys Identified Mail','Cryptographic signature proving the sending domain and that the message wasn&rsquo;t altered; public key in DNS.','1.3'),
('DLL','Dynamic Link Library','Shared Windows code. DLL injection and search-order hijacking load a malicious DLL into a trusted process.','1.2'),
('DLP','Data Loss Prevention','Detects and blocks sensitive data leaving, at rest, in motion and in use.','1.1'),
('DMARC','Domain-based Message Authentication, Reporting, and Conformance','Requires SPF or DKIM to align with the From domain; sets none/quarantine/reject and reporting.','1.3','Class sheet says &ldquo;Domain Message Authentication&rdquo;; the name starts &ldquo;Domain-based&rdquo;.'),
('DNS','Domain Name System','Name-to-IP resolution; watch for tunneling, DGA domains, and lookups of new domains.','1.3'),
('DoH','DNS over HTTPS','Carries DNS queries inside HTTPS on 443. Protects privacy but hides lookups from DNS monitoring and can bypass DNS filtering.','1.1'),
('DoS','Denial of Service','Making a service unavailable; from one source or by crashing it with a bug.','1.2'),
('DR','Disaster Recovery','Restoring IT after a major disruption; measured against RTO and RPO.','3.3'),
('EDR','Endpoint Detection and Response','Behavioral endpoint monitoring with remote response: isolate, kill, collect.','1.3'),
('EOF','End of File','Marks where data ends. Carving tools find files by their header signature and their footer or EOF marker.','3.2'),
('FIM','File Integrity Monitoring','Alerts when critical files change, by comparing hashes to a baseline.','1.2','Class sheet says &ldquo;File Integrity Management&rdquo;; the term is Monitoring.'),
('FTK','Forensic Toolkit','Forensic suite from Exterro (formerly AccessData). FTK Imager makes disk and memory images and verifies them with hashes.','3.2'),
('FTP','File Transfer Protocol','TCP 20/21, cleartext credentials and data; replace with SFTP.','1.2'),
('GDB','GNU Debugger','Command-line debugger for Linux/Unix programs.','2.2'),
('GPG','GNU Privacy Guard','Free OpenPGP tool for encrypting and signing files and email. Check a download&rsquo;s signature with <code>gpg --verify</code>.','1.1'),
('GPO','Group Policy Object','Push Windows settings and hardening baselines across a domain.','1.1'),
('HIDS','Host-based Intrusion Detection System','Monitors one host&rsquo;s logs, files and processes and alerts.','1.3'),
('HIPS','Host-based Intrusion Prevention System','Like HIDS, but blocks the activity.','1.3'),
('HTML','Hypertext Markup Language','Web page markup. User input placed into HTML without encoding is how XSS happens.','2.4'),
('HTTP','Hypertext Transfer Protocol','TCP 80, cleartext web traffic.','1.2'),
('HTTPD','Hypertext Transfer Protocol Daemon','The web server process, such as Apache&rsquo;s httpd. A shell started by httpd is a classic web-shell indicator.','1.2'),
('HTTPS','Hypertext Transfer Protocol Secure','HTTP over TLS, TCP 443; hides payloads from network tools without TLS inspection.','1.1'),
('IaaS','Infrastructure as a Service','Provider runs hardware; you manage OS and up.','1.1'),
('IAM','Identity and Access Management','Provisioning, authentication, authorization and access review. In the cloud, IAM policies are the main security control.','1.1'),
('ICMP','Internet Control Message Protocol','Ping, traceroute, unreachable messages; used for sweeps and sometimes tunneling.','1.2'),
('ICS','Industrial Control Systems','Control physical processes; scan passively, availability first.','2.1'),
('IDOR','Insecure Direct Object Reference','Changing an ID in a URL or request returns someone else&rsquo;s data because the server never checks ownership. A broken access control flaw.','2.4'),
('IDS','Intrusion Detection System','Detects and alerts, does not block; often fed a copy of traffic (SPAN or tap).','1.3'),
('IIS','Internet Information Services','Microsoft&rsquo;s web server. Its W3C access logs are a key source when investigating web attacks.','1.3'),
('IoC','Indicators of Compromise','Artifacts showing a breach happened: hashes, IPs, domains, registry keys.','1.4'),
('IP','Internet Protocol','Layer-3 addressing and routing.','1.1'),
('IPS','Intrusion Prevention System','Inline, can block; a false positive blocks legitimate traffic.','1.3'),
('IR','Incident Response','Preparation; detection and analysis; containment, eradication and recovery; post-incident.','3.2'),
('ISO','International Organization for Standardization','Publishes ISO/IEC 27001 (ISMS, certifiable) and 27002 (controls).','2.1','Class sheet says &ldquo;International Standards Organization&rdquo;, a common mistake; ISO is a short name, not an acronym of the English title.'),
('ISP','Internet Service Provider','Your upstream provider. Can help filter DDoS traffic and trace abuse.','1.1'),
('IT','Information Technology','Contrasted with OT, which controls physical processes.','2.1'),
('ITIL','Information Technology Infrastructure Library','IT service management framework: incident, problem and change management.','1.5'),
('JSON','JavaScript Object Notation','Key-value text format used by most APIs and many log pipelines.','1.3'),
('KPI','Key Performance Indicator','A metric tied to a goal, such as MTTD or percentage fixed within SLO.','4.1'),
('LAN','Local Area Network','One site&rsquo;s network; segment it with VLANs.','1.1'),
('LDAPS','Lightweight Directory Access Protocol','LDAP over TLS, TCP 636; plain LDAP is 389.','1.1','Class sheet leaves off what the S means: Secure, LDAP over SSL/TLS.'),
('LFI','Local File Inclusion','App includes a file already on the server via user input (<code>../</code> paths).','2.4'),
('LOI','Letter of Intent','Non-binding statement of intent to enter an agreement.','4.1'),
('LSASS','Local Security Authority Subsystem Service','Holds credentials in memory. Dumping lsass.exe (for example with Mimikatz) is a top credential-theft technique, so alert on access to it.','1.2'),
('MAC','Media Access Control','Layer-2 hardware address; spoofable, so weak for NAC on its own.','1.2'),
('MD5','Message Digest 5','128-bit hash, broken for collisions. Still used to identify files, but use SHA-256 to prove integrity.','1.3'),
('MFA','Multifactor Authentication','Two or more different factor types; two passwords is not MFA.','1.1'),
('MOU','Memorandum of Understanding','Statement of intent between parties; can limit when you can change shared systems.','4.1'),
('MSF','Metasploit Framework','Exploitation framework used to validate that a vulnerability is really exploitable.','2.2'),
('MSP','Managed Service Provider','Runs IT for clients; a supply-chain risk with wide access.','1.4'),
('MSRPC','Microsoft Remote Procedure Call','Windows RPC on TCP 135 plus dynamic ports. Used for lateral movement, so block it at the perimeter.','1.2'),
('MSSP','Managed Security Service Provider','Outsourced SOC monitoring and response.','1.5'),
('MTTD','Mean Time to Detect','Average time from compromise to detection; lower is better.','4.2'),
('MTTR','Mean Time to Repair','Exam objectives also use it for mean time to respond and mean time to remediate; read the context.','4.2','Not on the class sheet.'),
('NAC','Network Access Control','Checks device identity and health before granting network access (802.1X).','1.1'),
('NDA','Non-disclosure Agreement','Contract to keep information confidential; used with pen testers and vendors.','4.2'),
('NGFW','Next-generation Firewall','Application awareness, IPS, user identity and TLS inspection in one firewall.','1.1'),
('NIDS','Network-based Intrusion Detection System','Watches network traffic for attack patterns.','1.3'),
('NIPS','Network-based Intrusion Prevention System','Sits inline and blocks malicious traffic. A NIDS only watches and alerts.','1.1'),
('NIST','National Institute of Standards & Technology','US agency behind the CSF, SP 800-61 (incident handling) and SP 800-53 (security controls).','3.3'),
('NOC','Network Operations Center','Keeps the network up and running. The SOC watches for threats; the two coordinate during incidents.','1.5'),
('NTP','Network Time Protocol','UDP 123; keeps clocks in sync so logs correlate.','1.1'),
('OpenVAS','Open Vulnerability Assessment Scanner','Open-source network vulnerability scanner (Greenbone).','2.2','Class sheet calls it a standard for security testing; it is a vulnerability scanner (the testing standard is OSSTMM).'),
('OS','Operating System','Windows, Linux, macOS; know their log and config locations.','1.1'),
('OSINT','Open-source Intelligence','Intelligence from public sources: social media, DNS and WHOIS, job posts, breach dumps. Used for recon and threat intel.','1.4'),
('OSSTMM','Open Source Security Testing Methodology Manual','ISECOM&rsquo;s peer-reviewed method for measuring operational security.','3.1'),
('OSVDB','Open-Source Vulnerability DB','Community vulnerability database that shut down in 2016. CVE and the NVD are the references now.','2.3'),
('OT','Operational Technology','Hardware and software controlling physical processes; safety and availability first.','2.1'),
('OUI','Organizationally Unique Identifier','First 24 bits of a MAC address, identifying the vendor. Helps spot rogue or spoofed devices.','1.2'),
('OWASP','Open Web Application Security Project','Top 10, Testing Guide, ZAP.','2.1','Class sheet uses the old name; it was renamed Open Worldwide Application Security Project in 2023.'),
('PAM','Privileged Access Management','Vaults, rotates and monitors admin credentials; just-in-time elevation.','1.1'),
('PCI DSS','Payment Card Industry Data Security Standard','Required for anyone handling card data; quarterly internal and ASV external scans.','2.1'),
('PHP','Hypertext Preprocessor','Server-side web language; classic home of LFI/RFI flaws.','2.4'),
('PID','Process Identifier','Number of a running process; <code>netstat -ano</code> maps connections to PIDs.','1.3'),
('PII','Personally Identifiable Information','Data that identifies a person; drives breach-notification duties.','1.1'),
('PKI','Public Key Infrastructure','CAs, certificates, revocation (CRL, OCSP).','1.1'),
('PLC','Programmable Logic Controller','Industrial controller running a physical process; can crash under active scans.','2.1'),
('POC','Proof of Concept','Code showing a vulnerability is exploitable; public POC raises priority.','2.3'),
('RADIUS','Remote Authentication Dial-in User Service','Central AAA for VPN, Wi-Fi (802.1X) and network devices, on UDP 1812/1813.','1.1'),
('RCE','Remote Code Execution','Attacker runs commands on a system over the network; typically critical.','2.4'),
('RDP','Remote Desktop Protocol','TCP 3389; brute-forced and abused for lateral movement; never expose to the internet.','1.2'),
('REST','Representational State Transfer','API style using HTTP verbs, usually with JSON.','1.5'),
('RFI','Remote File Inclusion','App includes a file from an attacker&rsquo;s URL; leads to RCE.','2.4'),
('RPC','Remote Procedure Call','One program calling a function on another system. The basis for MSRPC and many admin tools.','1.1'),
('RPO','Recovery Point Objective','Most data you can afford to lose, measured back in time from the outage. Drives how often you back up.','3.3'),
('RSA','Rivest Shamir & Adleman','Asymmetric algorithm for key exchange and digital signatures. 2048-bit keys are the current minimum.','1.1'),
('RTO','Recovery Time Objective','Longest a service may stay down before it must be restored.','3.3'),
('RXSS','Reflected Cross-site Scripting','Script in a request is echoed back immediately; victim must follow a crafted link.','2.4'),
('SaaS','Software as a Service','Provider runs everything; you manage data, users and configuration.','1.1'),
('SAML','Security Assertion Markup Language','XML assertions from an IdP for federated web SSO.','1.1','Class sheet says &ldquo;Assertions&rdquo;; it is Assertion, singular.'),
('SAMM','Software Assurance Maturity Model','OWASP model for measuring and improving a software security program.','2.5'),
('SASE','Secure Access Service Edge','Cloud-delivered SD-WAN plus SWG, CASB, ZTNA and FWaaS.','1.1'),
('SAST','Static Application Security Testing','Analyzes source code without running it. Finds flaws early and points to the exact line, but produces false positives.','2.1'),
('SCADA','Supervisory Control and Data Acquisition','Wide-area ICS (grids, pipelines, water).','2.1'),
('SDLC','Software Development Life Cycle','Secure SDLC builds security into every phase.','2.5'),
('SDN','Software-defined Networking','Separates control plane (controller) from data plane (forwarding).','1.1'),
('SFTP','Secure File Transfer Protocol','File transfer over SSH, TCP 22.','1.1','Class sheet says &ldquo;Secured&rdquo;; the protocol is the SSH File Transfer Protocol.'),
('SIEM','Security Information and Event Management','Collects, normalizes, correlates and alerts on logs.','1.3'),
('SLA','Service-level Agreement','Contractual service commitments; uptime promises can block patch windows.','4.1'),
('SLO','Service-level Objective','Measurable target, such as criticals fixed within 7 days.','2.5'),
('SMB','Server Message Block','Windows file sharing, TCP 445; workstation-to-workstation SMB suggests lateral movement.','1.2'),
('SMS','Short Message Service','Text messages. SMS one-time codes are the weakest MFA option because of SIM swapping and interception.','1.1'),
('SMTP','Simple Mail Transfer Protocol','Mail transfer, TCP 25 (587 for submission).','1.3'),
('SNI','Server Name Indication','TLS extension that sends the requested hostname unencrypted, so proxies and firewalls can see which site an HTTPS session is for.','1.3','Class sheet says &ldquo;SMS Notification Indicator&rdquo; and gives SOAP&rsquo;s definition; both are wrong.'),
('SNMP','Simple Network Management Protocol','Device monitoring, UDP 161/162; v1/v2c use cleartext community strings, prefer v3.','1.1'),
('SOAP','Simple Object Access Protocol','XML-based web service messaging. Exposed to XML attacks such as XXE.','2.4'),
('SOAR','Security Orchestration, Automation, and Response','Runs playbooks to enrich, contain and ticket automatically.','1.5'),
('SOC','Security Operations Center','The team and facility doing monitoring and triage.','1.5'),
('SPF','Sender Policy Framework','DNS TXT listing servers allowed to send for a domain&rsquo;s envelope sender.','1.3'),
('SQL','Structured Query Language','Database language; SQL injection is fixed with parameterized queries.','2.4'),
('SQLi','SQL Injection','Input that changes a database query. Prevent with parameterized queries and input validation.','2.4'),
('SSH','Secure Shell','Encrypted remote administration on TCP 22. Watch for brute force and for keys added to authorized_keys.','1.1'),
('SSID','Service Set Identifier','Wi-Fi network name. A second access point broadcasting your SSID is an evil twin.','1.2'),
('SSL','Secure Sockets Layer','Deprecated predecessor of TLS; the name survives in &ldquo;SSL inspection&rdquo;.','1.1'),
('SSO','Single Sign-on','One login, many apps.','1.1'),
('SSRF','Server-side Request Forgery','Server is tricked into requesting internal resources such as cloud metadata.','2.4'),
('STIX','Structured Threat Information Expression','Standard format for threat intel; transported by TAXII.','1.4','Class sheet says &ldquo;eXchange&rdquo;; the X is for eXpression.'),
('SWG','Secure Web Gateway','Filters user web traffic: URL categories, malware scanning, DLP.','1.1'),
('TCP','Transmission Control Protocol','Connection-oriented; SYN, SYN-ACK, ACK handshake.','1.2'),
('TFTP','Trivial File Transfer Protocol','UDP 69, no authentication; used for device configs and firmware.','1.2'),
('TLS','Transport Layer Security','Encrypts traffic in transit; use 1.2 or 1.3.','1.1'),
('TRACE','Trade Reporting and Compliance Engine','FINRA&rsquo;s bond trade-reporting system; on the list but rarely tested.','4.2'),
('TTP','Tactics, Techniques, and Procedures','How an adversary operates; the most durable intel (top of the Pyramid of Pain).','1.4'),
('UDP','User Datagram Protocol','Connectionless transport used by DNS, NTP, SNMP and syslog, and abused for amplification DDoS.','1.1'),
('UEBA','User and Entity Behavior Analytics','Baselines users and devices to flag anomalies such as impossible travel.','1.3'),
('URI','Uniform Resource Identifier','Identifies a resource; a URL is a URI that also gives its location.','1.3'),
('URL','Uniform Resource Locator','Web address; obfuscated URLs hide phishing destinations.','1.2','Class sheet says &ldquo;Universal Resource Locator&rdquo;; it is Uniform.'),
('USB','Universal Serial Bus','Removable media is a delivery vector; control with DLP and device policy.','1.2'),
('UTC','Coordinated Universal Time','The time standard for logs. Record and correlate in UTC to build timelines across time zones.','3.2','Class sheet says &ldquo;Universal Time Coordinated&rdquo;; the standard name is Coordinated Universal Time.'),
('VLAN','Virtual Local Area Network','Layer-2 segmentation on one switch infrastructure.','1.1'),
('VM','Virtual Machine','Guest OS on a hypervisor; snapshot for forensics.','1.1'),
('VPN','Virtual Private Network','Encrypted tunnel; VPN egress can trigger false impossible-travel alerts.','1.1'),
('WAF','Web Application Firewall','Inspects HTTP to block XSS, SQLi and similar; useful compensating control.','2.4'),
('WAN','Wide Area Network','Connects sites; SD-WAN is part of SASE.','1.1'),
('XDR','Extended Detection and Response','EDR-style detection correlated across endpoint, network, email, identity and cloud.','1.3'),
('XML','Extensible Markup Language','Tagged data format; SAML and Windows event exports use it.','1.3'),
('XSS','Cross-site Scripting','Injected script runs in other users&rsquo; browsers; fix with output encoding.','2.4'),
('XXE','XML External Entity','XML parser resolves an attacker&rsquo;s entity to read files or make requests; disable external entities.','2.4'),
('ZAP','Zed Attack Proxy','OWASP&rsquo;s free intercepting proxy and web scanner.','2.2'),
('ZTA','Zero Trust Architecture','Design based on never trust, always verify (NIST SP 800-207). ZTNA is one part of it.','1.1'),
('ZTNA','Zero Trust Network Access','Per-app access after verifying user and device; replaces broad VPN access.','1.1'),
]
CLASS_ONLY = ['ASVS', 'ATT&CK', 'BEAST', 'BIOS', 'BREACH', 'CBC', 'CMS', 'CPU', 'CSF', 'DAST', 'DEP', 'DHCP', 'DLL', 'DoH', 'EOF', 'FTK', 'GPG', 'HTML', 'HTTPD', 'IAM', 'IDOR', 'IIS', 'ISP', 'LSASS', 'MD5', 'MSRPC', 'NIPS', 'NIST', 'NOC', 'OSINT', 'OSVDB', 'OUI', 'RADIUS', 'RPC', 'RPO', 'RSA', 'RTO', 'SAMM', 'SAST', 'SMS', 'SNI', 'SOAP', 'SQLi', 'SSH', 'SSID', 'UDP', 'UTC', 'ZTA']
